  output.append({'id':mid+'.'+str(i).zfill(2),'parent':mid,'condition':f,'original_requirement':o['requirement'],'original_acceptance':o['acceptance'],'original_acceptance_sha256':hashlib.sha256(o['acceptance'].encode()).hexdigest(),'closure_steps':steps.split(','),'existing_scope_from_current_index':cr.get('current_supported_scope'),'source':'data/accounting-master/acceptance-priority-20261027/release-acceptance.json#'+mid,'evidence_class':'inherited_supported_scope_not_new_clause_acceptance','acceptance_status':'needs_exact_clause_evidence_and_independent_acceptance','necessary_condition_review':necessary.get(mid),'disposition':'No original condition waived; a selected example is not automatically a necessary condition.'})
